function pgEscape(v){ if(v===null||v===undefined) return 'NULL'; if(typeof v==='number') return String(v); if(typeof v==='boolean') return v?'TRUE':'FALSE'; const s=String(v); return "'"+s.replace(/'/g,"''")+"'"; }
function buildSql(o){
  const cols=['hash','country','source','title','title_normalized','company','location','remote_type','url','jd_text','raw_payload','posted_at','filter_status','keyword_score'];
  const vals=[pgEscape(o.hash),pgEscape(o.country),pgEscape(o.source),pgEscape(o.title),pgEscape(o.title_normalized),pgEscape(o.company),pgEscape(o.location),pgEscape(o.remote_type),pgEscape(o.url),pgEscape(o.jd_text),pgEscape(JSON.stringify(o.raw_payload))+'::jsonb',pgEscape(o.posted_at)+'::timestamptz',pgEscape(o.filter_status||'new'),(o.keyword_score==null?'0':String(o.keyword_score))];
  return `INSERT INTO jobs (${cols.join(',')}) VALUES (${vals.join(',')}) ON CONFLICT (hash) DO UPDATE SET scraped_at=NOW() RETURNING id, title, company, location, url, jd_text, hash, (xmax = 0) AS is_new;`;
}

const input  = $('Set Input').first().json;
const loaded = $input.first().json;
const domain   = input.domain;
const country  = input.country;
const profile  = loaded.profile || {};
const blocklist = loaded.blocklist || [];
const targetRoles = (profile.wants && profile.wants.roles) || [domain];
const query = domain;

const sgaiKey   = 'sgai-1fb2fd2c-1a89-45f5-94d1-89d036ae24fb';
const adzunaId  = $env.ADZUNA_APP_ID;
const adzunaKey = $env.ADZUNA_APP_KEY;
const joobleKey = $env.JOOBLE_KEY;
const serpKey   = $env.SERPAPI_KEY;

const adzunaCC  = { IE:'gb', AE:'gb', AU:'au', US:'us' }[country] || 'gb';
const locName   = { IE:'Ireland', AE:'United Arab Emirates', AU:'Australia' }[country] || 'Ireland';

const helpers = this.helpers;
const safe = async (name, opts) => {
  try { const data = await helpers.httpRequest({ ...opts, json:true, ignoreHttpStatusErrors:true, timeout:35000 });
        return { source:name, ok:true, data }; }
  catch(e){ return { source:name, ok:false, error:String(e).slice(0,200) }; }
};

const calls = [];

// 1. Adzuna (3 pages = up to 150 results)
if (adzunaId && adzunaKey) for (let p=1; p<=3; p++) {
  calls.push(safe(`adzuna:p${p}`, { method:'GET',
    url:`https://api.adzuna.com/v1/api/jobs/${adzunaCC}/search/${p}`,
    qs:{ app_id:adzunaId, app_key:adzunaKey, results_per_page:50, what:query, where:locName, max_days_old:14 } }));
}

// 2. Jooble (3 pages)
if (joobleKey) for (let p=1; p<=3; p++) {
  calls.push(safe(`jooble:p${p}`, { method:'POST',
    url:`https://jooble.org/api/${joobleKey}`,
    headers:{ 'Content-Type':'application/json' },
    body:{ keywords:query, location:locName, page:String(p) } }));
}

// 3. Greenhouse PUBLIC API — direct JSON, no SGAI needed (10× more reliable)
const ghBoards = ['stripe','intercom','hubspot','openai','anthropic','ramp','brex','figma','databricks','airbnb','retool','vercel','snowflake','mongodb','workday','datadog'];
for (const b of ghBoards) {
  calls.push(safe(`gh:${b}`, { method:'GET',
    url:`https://boards-api.greenhouse.io/v1/boards/${b}/jobs?content=true` }));
}

// 4. Lever PUBLIC API — direct JSON
const leverCos = ['spotify','netflix','palantir','scaleai','replicate','mistral','huggingface','plaid','attentive'];
for (const c of leverCos) {
  calls.push(safe(`lever:${c}`, { method:'GET',
    url:`https://api.lever.co/v0/postings/${c}?mode=json` }));
}

// 5. Ashby PUBLIC API — direct JSON
const ashbyCos = ['linear','supabase','posthog','runwayml','perplexity','elevenlabs','cursor'];
for (const c of ashbyCos) {
  calls.push(safe(`ashby:${c}`, { method:'GET',
    url:`https://api.ashbyhq.com/posting-api/job-board/${c}?includeCompensation=true` }));
}

// 6. RemoteOK (no key needed)
calls.push(safe('remoteok', { method:'GET', url:'https://remoteok.com/api', headers:{ 'User-Agent':'job-radar/1.0' } }));

// 7. ScrapeGraphAI — used for messy company careers pages (no public API)
//    Smart-extract with structured output schema
const sgaiTargets = [
  { name:'sgai:google-careers', url:`https://www.google.com/about/careers/applications/jobs/results/?q=${encodeURIComponent(query)}&location=${encodeURIComponent(locName)}` },
  { name:'sgai:apple-careers',  url:`https://jobs.apple.com/en-us/search?search=${encodeURIComponent(query)}&sort=relevance&location=${country.toLowerCase()}-IRL` },
  { name:'sgai:meta-careers',   url:`https://www.metacareers.com/jobs?q=${encodeURIComponent(query)}` }
];
for (const t of sgaiTargets) {
  calls.push(safe(t.name, { method:'POST',
    url:'https://api.scrapegraphai.com/v1/smartscraper',
    headers:{ 'SGAI-APIKEY':sgaiKey, 'Content-Type':'application/json' },
    body:{
      website_url: t.url,
      user_prompt: `Extract every job posting visible on this page. Return strict JSON: {"jobs":[{"title":"","location":"","url":"","department":""}]}. Include up to 50 jobs.`,
      output_schema:{ type:'object', properties:{ jobs:{ type:'array', items:{ type:'object', properties:{ title:{type:'string'}, location:{type:'string'}, url:{type:'string'}, department:{type:'string'} }, required:['title','url'] } } } }
    }
  }));
}

// 8. SerpAPI Google Jobs (if key present)
if (serpKey) {
  calls.push(safe('serpapi:googlejobs', { method:'GET',
    url:'https://serpapi.com/search.json',
    qs:{ engine:'google_jobs', q:`${query} ${locName}`, hl:'en', api_key:serpKey } }));
}

const results = await Promise.all(calls);

const crypto = require('crypto');
const now = new Date().toISOString();
const all = [];
const debug = [];

for (const r of results) {
  if (!r.ok) { debug.push(`${r.source}: ERR`); continue; }
  let jobs = [];
  const s = r.source;
  try {
    if (s.startsWith('adzuna:')) {
      jobs = (r.data.results||[]).map(j=>({ source:'adzuna', title:j.title, company:j.company?.display_name, location:j.location?.display_name, url:j.redirect_url, jd_text:j.description, posted_at:j.created }));
    } else if (s.startsWith('jooble:')) {
      jobs = (r.data.jobs||[]).map(j=>({ source:'jooble', title:j.title, company:j.company, location:j.location, url:j.link, jd_text:j.snippet, posted_at:j.updated }));
    } else if (s.startsWith('gh:')) {
      const co = s.split(':')[1];
      jobs = (r.data.jobs||[]).map(j=>({ source:s, title:j.title, company:co, location:j.location?.name, url:j.absolute_url, jd_text:(j.content||'').replace(/<[^>]+>/g,' ').slice(0,3000), posted_at:j.updated_at }));
    } else if (s.startsWith('lever:')) {
      const co = s.split(':')[1];
      jobs = (Array.isArray(r.data)?r.data:[]).map(j=>({ source:s, title:j.text, company:co, location:j.categories?.location, url:j.hostedUrl, jd_text:(j.descriptionPlain||'').slice(0,3000), posted_at:new Date(j.createdAt||Date.now()).toISOString() }));
    } else if (s.startsWith('ashby:')) {
      const co = s.split(':')[1];
      jobs = (r.data.jobs||[]).map(j=>({ source:s, title:j.title, company:co, location:j.locationName||j.location, url:j.jobUrl||j.applyUrl, jd_text:(j.descriptionPlain||'').slice(0,3000), posted_at:j.publishedDate||now }));
    } else if (s==='remoteok') {
      jobs = (Array.isArray(r.data)?r.data.slice(1):[]).map(j=>({ source:'remoteok', title:j.position, company:j.company, location:j.location||'Remote', url:j.url, jd_text:(j.description||'').replace(/<[^>]+>/g,' ').slice(0,3000), posted_at:j.date }));
    } else if (s.startsWith('sgai:')) {
      const arr = r.data?.result?.jobs || r.data?.jobs || [];
      jobs = arr.map(j=>({ source:s, title:j.title, company:s.split(':')[1].split('-')[0], location:j.location, url:j.url, jd_text:j.department||'', posted_at:now }));
    } else if (s==='serpapi:googlejobs') {
      jobs = (r.data.jobs_results||[]).map(j=>({ source:'serpapi', title:j.title, company:j.company_name, location:j.location, url:j.related_links?.[0]?.link||j.share_link, jd_text:(j.description||'').slice(0,3000), posted_at:now }));
    }
  } catch(e) { debug.push(`${s}:parse-err`); }
  jobs = jobs.filter(j=>j && j.title && j.url);
  debug.push(`${s}:${jobs.length}`);
  all.push(...jobs);
}

// Dedupe by URL early
const seenUrl = new Set();
const dedup = all.filter(j=>{ if(seenUrl.has(j.url)) return false; seenUrl.add(j.url); return true; });

// Domain keyword filter (loose: title OR jd_text)
const domainTokens = domain.toLowerCase().split(/\s+/).filter(t=>t.length>2);
const passDomain = j => {
  const hay = ((j.title||'')+' '+(j.jd_text||'')).toLowerCase();
  return domainTokens.some(t => hay.includes(t));
};

// Blocklist on title (senior/principal/director/etc)
const blockRe = blocklist.length ? new RegExp('\\b('+blocklist.join('|').replace(/[+]/g,'\\+')+')\\b','i') : null;

const filtered = dedup.filter(j=>{
  if (blockRe && blockRe.test(j.title)) return false;
  if (!passDomain(j)) return false;
  return true;
}).map(j=>{
  const hash = crypto.createHash('sha256').update(j.url).digest('hex').slice(0,32);
  const titleLow = (j.title||'').toLowerCase();
  return {
    hash, country, source:j.source,
    title:j.title, title_normalized:titleLow,
    company:j.company||'Unknown',
    location:j.location||locName,
    remote_type:/remote/i.test((j.location||'')+' '+j.title) ? 'remote' : null,
    url:j.url,
    jd_text:(j.jd_text||'').slice(0,4000),
    raw_payload:JSON.stringify(j),
    posted_at:j.posted_at||now,
    filter_status:'passed',
    keyword_score: domainTokens.filter(t=>titleLow.includes(t)).length / Math.max(1,domainTokens.length),
    domain,
    _debug:debug.join(' | ')
  };
});

if (filtered.length === 0) {
  return [{ json:{ _empty:true, sql:"SELECT 1 WHERE FALSE", _debug:debug.join(' | '), _all_count:all.length }}];
}
return filtered.slice(0,80).map(j=>({ json:{ ...j, sql: buildSql(j) }}));

// fetch shim using n8n helper
async function fetch(url, opts = {}) {
  const res = await this.helpers.httpRequest({
    url,
    method: opts.method || 'GET',
    headers: opts.headers || {},
    body: opts.body ? (typeof opts.body === 'string' ? JSON.parse(opts.body) : opts.body) : undefined,
    json: true,
    returnFullResponse: false,
    ignoreHttpStatusErrors: true
  });
  return { ok: true, json: async () => res, status: 200 };
}
fetch = fetch.bind(this);

// Aggregate jobs and call OpenRouter LLM to rank top N
const input = $('Set Input').first().json;
const loaded = $('Load Profile').first().json;
const profile = loaded.profile;
const topN = input.top_n;
const domain = input.domain;

const items = $input.all().map(i => i.json);
if (items.length === 0) return [{ json: { skip: true, reason: 'no_jobs', count: 0 }}];

const candidatesText = items.slice(0, 30).map((j, i) => `[${i+1}] id=${j.id} | ${j.title} @ ${j.company} | ${j.location} | ${j.url}\n   ${(j.jd_text||'').slice(0, 200)}`).join('\n\n');

const prompt = `You are a career strategist. Rank the BEST ${topN} jobs for this candidate.\n\nCANDIDATE PROFILE:\n${JSON.stringify(profile, null, 2)}\n\nDOMAIN FOCUS: ${domain}\n\nCANDIDATES (${items.length}):\n${candidatesText}\n\nReturn STRICT JSON only:\n{\"top\": [{\"id\": <id>, \"score\": 0-100, \"reason\": \"1 short sentence\"}]}\n\nRules: reject senior/lead/staff/manager. Reward fit with skills. Prefer fresh, direct company boards. Sort by score desc.`;

const resp = await fetch('https://openrouter.ai/api/v1/chat/completions', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${$env.OPENROUTER_KEY}`,
    'Content-Type': 'application/json',
    'HTTP-Referer': 'https://github.com/gauthambinoy/job-radar'
  },
  body: JSON.stringify({
    model: $env.OPENROUTER_MODEL || 'google/gemini-2.0-flash-lite-001',
    messages: [{ role: 'user', content: prompt }],
    response_format: { type: 'json_object' },
    temperature: 0.2
  })
});
const data = await resp.json();
const raw = data.choices?.[0]?.message?.content || '{}';
let ranked;
try { ranked = JSON.parse(raw); } catch(e) {
  const m = raw.match(/\{[\s\S]*\}/); ranked = m ? JSON.parse(m[0]) : { top: [] };
}
if (Array.isArray(ranked)) ranked = ranked[0] || { top: [] };
if (ranked && !ranked.top && ranked.jobs) ranked.top = ranked.jobs;
const byId = Object.fromEntries(items.map(j => [j.id, j]));
const top = (ranked.top || []).slice(0, topN).map((r, i) => ({
  rank: i+1, id: r.id, score: r.score, reason: r.reason, ...byId[r.id]
})).filter(r => r.title);

return [{ json: { skip: false, count: items.length, top, domain, country: input.country, _llm_raw: raw.slice(0, 800), _llm_status: data?.error?.message || "ok", _llm_model: data?.model }}];

// Build concise digest + verify top links before Telegram
async function request(opts) {
  return await this.helpers.httpRequest({
    ...opts,
    ignoreHttpStatusErrors: true,
    timeout: opts.timeout || 30000,
  });
}
request = request.bind(this);

async function sendTelegram(payload) {
  return await request({
    method: 'POST',
    url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
    headers: {'Content-Type': 'application/json'},
    body: payload,
    json: true,
    timeout: 30000,
  });
}

function sourceFromUrl(url) {
  const u = String(url || '').toLowerCase();
  if (u.includes('linkedin.')) return 'LinkedIn';
  if (u.includes('indeed.')) return 'Indeed';
  if (u.includes('greenhouse.io')) return 'Greenhouse';
  if (u.includes('lever.co')) return 'Lever';
  if (u.includes('ashbyhq.com')) return 'Ashby';
  return 'Job source';
}

async function verifyJob(j) {
  const url = String(j.url || '').trim();
  const out = { ...j, source_label: sourceFromUrl(url), verified_link: false, verify_status: null, verify_note: 'not_checked' };
  if (!/^https?:\/\//i.test(url)) {
    out.verify_note = 'bad_url';
    return out;
  }
  try {
    const resp = await request({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/124 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
      },
      json: false,
      returnFullResponse: true,
      timeout: 15000,
    });
    const status = Number(resp.statusCode || resp.status || 0);
    const body = String(resp.body || '').slice(0, 180000).toLowerCase();
    const expired = [
      'no longer accepting applications',
      'job has expired',
      'job expired',
      'job is no longer available',
      'this job is no longer available',
      'page not found'
    ].some(s => body.includes(s));
    out.verify_status = status || null;
    if (expired) {
      out.verify_note = 'expired_or_closed_marker';
      return out;
    }
    const isLinkedIn = /linkedin\./i.test(url);
    out.verified_link = (status >= 200 && status < 400) || (isLinkedIn && [403, 429, 999].includes(status));
    out.verify_note = out.verified_link ? 'http_checked' : 'bad_http_status';
    return out;
  } catch (e) {
    out.verify_note = 'error:' + String(e).slice(0, 100);
    return out;
  }
}

const d = $input.first().json;
if (d.skip) {
  return [{ json: { sent: false, reason: d.reason }}];
}

const checked = [];
for (const job of (d.top || [])) {
  checked.push(await verifyJob(job));
}
const verified = checked.filter(j => j.verified_link);
const display = (verified.length ? verified : checked).slice(0, d.top?.length || 10);

const date = new Date().toISOString().slice(0,10);
const lines = [`TOP ${display.length} VERIFIED-CHECKED JOBS - ${d.domain} - ${d.country} - ${date}`, `Verified working links: ${verified.length}/${checked.length}`, ''];
for (const j of display) {
  const rank = j.rank || display.indexOf(j) + 1;
  const status = j.verify_status ? `HTTP ${j.verify_status}` : j.verify_note;
  lines.push(`${rank}. [${j.score}] ${j.company} - ${j.title}`);
  lines.push(`Source: ${j.source_label} | ${j.location || '-'} | ${j.verified_link ? 'verified' : 'not verified'} (${status})`);
  lines.push(`Link: ${j.url}`);
  lines.push(`Why: ${String(j.reason || '').slice(0, 240)}`);
  lines.push('');
}
if (!verified.length) {
  lines.push('No top links passed the working-link check, so these are shown for debugging only.');
}
const text = lines.join('\n');

const tg = await sendTelegram({
  chat_id: $env.TELEGRAM_CHAT_ID || '8047661784',
  text,
  disable_web_page_preview: true
});

return [{
  json: {
    sent: tg.ok,
    message_id: tg.result?.message_id,
    count: display.length,
    verified_count: verified.length,
    candidates: d.count,
    domain: d.domain,
    country: d.country,
    top: display,
    digest_preview: text.slice(0, 500)
  }
}];

