const body = $input.first().json.body || $input.first().json || {};
const token = $env.TELEGRAM_BOT_TOKEN;
const defaultChatId = $env.TELEGRAM_CHAT_ID || '8047661784';
const runnerSecret = '29aec07b9ef3d833b04dd8cc852c48e380d0cc0aa90ce312';
const runnerUrl = 'http://172.17.0.1:8787/run-codex';
const jobRadarUrl = 'https://n8n.52.212.112.133.nip.io/webhook/job-radar';

async function http(opts) {
  return await this.helpers.httpRequest({
    ...opts,
    json: true,
    ignoreHttpStatusErrors: true,
    timeout: opts.timeout || 30000,
  });
}
http = http.bind(this);

async function tg(method, payload) {
  return await http({
    method: 'POST',
    url: `https://api.telegram.org/bot${token}/${method}`,
    body: payload,
    timeout: 30000,
  });
}

function chatIdFrom(update) {
  return update.callback_query?.message?.chat?.id || update.message?.chat?.id || defaultChatId;
}

const callback = body.callback_query;
const message = body.message;
const chat_id = String(chatIdFrom(body));
const data = callback?.data || '';
const text = String(message?.text || '').trim();

let action = 'ignore';
if (callback && data === 'job_codex') action = 'codex';
else if (callback && data === 'job_sources') action = 'sources';
else if (callback && data === 'job_menu') action = 'menu';
else if (/^\/?(jobs|jobsearch|start)\b/i.test(text)) action = 'menu';

if (callback?.id) {
  const label = action === 'codex' ? 'Starting Codex search' : action === 'sources' ? 'Starting other sources' : 'Opening menu';
  await tg('answerCallbackQuery', { callback_query_id: callback.id, text: label });
}

if (action === 'menu') {
  await tg('sendMessage', {
    chat_id,
    text: 'Choose job search mode:',
    disable_web_page_preview: true,
    reply_markup: {
      inline_keyboard: [
        [{ text: 'Codex: LinkedIn + Indeed', callback_data: 'job_codex' }],
        [{ text: 'Other sources: ATS + aggregators', callback_data: 'job_sources' }],
      ],
    },
  });
  return [{ json: { ok: true, action, chat_id } }];
}

if (action === 'codex') {
  await tg('sendMessage', {
    chat_id,
    text: 'Starting Codex search for verified LinkedIn and Indeed jobs. Results will arrive here after link checks finish.',
    disable_web_page_preview: true,
  });
  const runner = await http({
    method: 'POST',
    url: runnerUrl,
    headers: { 'X-Job-Runner-Secret': runnerSecret },
    body: {
      chat_id,
      countries: ['Ireland', 'UAE/Dubai', 'Australia'],
      limit: 20,
    },
    timeout: 30000,
  });
  return [{ json: { ok: true, action, chat_id, runner } }];
}

if (action === 'sources') {
  await tg('sendMessage', {
    chat_id,
    text: 'Starting n8n other-sources search for Ireland, UAE/Dubai, and Australia. Job Radar will send the digests here.',
    disable_web_page_preview: true,
  });
  const countries = ['IE', 'AE', 'AU'];
  const results = [];
  for (const country of countries) {
    try {
      const res = await http({
        method: 'POST',
        url: jobRadarUrl,
        body: {
          domain: 'AI Engineer Software Engineer Graduate Junior Backend Full Stack',
          country,
          top_n: 10,
        },
        timeout: 600000,
      });
      results.push({ country, ok: true, response: res });
    } catch (e) {
      results.push({ country, ok: false, error: String(e).slice(0, 300) });
      await tg('sendMessage', {
        chat_id,
        text: `Other-sources search failed for ${country}: ${String(e).slice(0, 500)}`,
      });
    }
  }
  await tg('sendMessage', {
    chat_id,
    text: 'Other-sources search finished. Any matching digests should now be above.',
    disable_web_page_preview: true,
  });
  return [{ json: { ok: true, action, chat_id, results } }];
}

return [{ json: { ok: true, action, ignored: true, chat_id } }];

// === Normalise Input (v5 — Claude only, tier-based) ===
let input = $input.first().json || {};
// FALLBACK: if JD missing (queue branch stripped data), recover from Filter Due / Read Pending
if (!input['Job Description'] || String(input['Job Description']).trim().length < 30) {
  try {
    const fd = $('Queue: Filter Due').all();
    if (fd && fd[0] && fd[0].json && fd[0].json.JD) {
      const j = fd[0].json;
      input = {
        'Job Description': j.JD || '',
        'Job URL':         j.URL || '',
        'CV Mode':         j.MODE || 'Professional',
        'Tier':            j.TIER || 'Balanced',
        'Your Name':       j.NAME || 'Gautham',
        'Location':        j.LOCATION || '',
        row_number:        j.row_number,
        _queueRowNumber:   j.row_number,
        _queueSheetId:     '1aaBiwgS_zw3IZ0gkKKbLJpo_98bkzIPVx7vgbv-fxjM',
        _recovered:        'filter-due',
      };
    }
  } catch(e) { /* not in scheduled branch */ }
