} }];

// Error context formatter — fetches Form Trigger input via n8n API
// ⚠️ API key reissued 2026-06-26 (no expiry). If it 401s, regenerate in n8n UI (Settings → API).
// On JWT expiry, the API fetch fails gracefully (catch block) — Telegram still fires
// without form context. _fetch_error will say "401" or "AbortError".
const exec = $json.execution || {};
const wf = $json.workflow || {};
const err = exec.error || {};
const failedNode = err.node || (typeof err === 'object' ? (err.lastNodeExecuted || 'unknown') : 'unknown');

const API_KEY = process.env.N8N_API_KEY || '';  // #8 2026-07: moved out of code; set N8N_API_KEY env in docker-compose
let formData = {};
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://localhost:5678/api/v1/executions/' + exec.id + '?includeData=true',
    headers: { 'X-N8N-API-KEY': API_KEY },
    json: true
  });
  const rd = resp && resp.data && resp.data.resultData && resp.data.resultData.runData;
  if (rd) {
    const norm = rd['Normalise Input'];
    if (norm && norm[0] && norm[0].data && norm[0].data.main && norm[0].data.main[0] && norm[0].data.main[0][0]) {
      formData = norm[0].data.main[0][0].json || {};
    }
    // Also try Form Trigger directly
    if (!formData.jd && !formData.url) {
      const ft = rd['Form Trigger'];
      if (ft && ft[0] && ft[0].data && ft[0].data.main && ft[0].data.main[0] && ft[0].data.main[0][0]) {
        formData = Object.assign(formData, ft[0].data.main[0][0].json || {});
      }
    }
  }
} catch (e) {
  formData = { _fetch_error: String(e).slice(0, 200) };
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    workflow_name: wf.name || 'TOP RESUMAE 2026',
    execution_id: exec.id || 'unknown',
    execution_url: exec.url || ('https://n8n.34.248.143.39.nip.io/workflow/' + (wf.id || 'S5UYbSbCFhMFpCWc') + '/executions/' + (exec.id || '')),
    failed_node: typeof failedNode === 'object' ? (failedNode.name || JSON.stringify(failedNode).slice(0,100)) : String(failedNode),
    error_message: err.message || 'No error message',
    error_stack: (err.stack || '').slice(0, 500),
    company: formData.company || formData.formattedCompany || formData.Company || 'Unknown',
    role_title: formData.roleTitle || formData.role || formData.Role || formData['Job Title'] || 'Unknown',
    job_url: formData.url || formData.jobUrl || formData['Job URL'] || 'none',
    mode: formData.mode || formData.cvModeLabel || formData.Mode || 'unknown',
    tier: formData.tier || formData.tierLabel || formData.Tier || 'unknown',
    jd_preview: String(formData.jd || formData.jdRaw || formData['Job Description'] || '').slice(0, 600),
    candidate_email: formData.candidateEmail || formData.email || formData.Email || 'jobhunter20266@gmail.com',
    _form_keys_seen: Object.keys(formData).slice(0, 15).join(',')
  }
}];

