// === Hc · Build Replacements (Healthcare lane, 2 roles 8+6 bullets, 6 skills, 3 projects, 4 certs) ===
// Updated 2026-05-25: template has PROJECT_IDEA + CERTIFICATION placeholders, now substituted.
try {
  const parseOut = $('Hc · Parse Output').item.json || {};
  const item = parseOut;
  const cv = parseOut.cv_content || (parseOut.data && parseOut.data.cv_content) || {};
  const meta = item.meta || (item.data && item.data.meta) || {};

  const copied = $('Hc · Copy Template').item.json || {};
  const docId = copied.id || copied.fileId || copied.docId || '';

  const str = (v) => (v === null || v === undefined) ? '' : String(v);
  const cap = (s) => str(s).slice(0, 100000);
  const bullet = (arr, i) => cap((Array.isArray(arr) ? arr[i] : '') || '');
  const _safe = (fn, def) => { try { const v = fn(); return (v === null || v === undefined) ? def : v; } catch(e){ return def; } };

  const replaceMap = {};
  replaceMap['{PROFESSIONAL_SUMMARY}'] = cap(cv.professional_summary);

  // role_1: 8 bullets
  for (let i = 1; i <= 8; i++) {
    replaceMap[`{ROLE_1_ACHIEVEMENT_BULLET_${i}_AI_GENERATED_FROM_JD}`] = bullet(cv.role_1_bullets, i - 1);
  }
  // role_2: 6 bullets
  for (let i = 1; i <= 6; i++) {
    replaceMap[`{ROLE_2_ACHIEVEMENT_BULLET_${i}_AI_GENERATED_FROM_JD}`] = bullet(cv.role_2_bullets, i - 1);
  }
  // 6 skills
  for (let i = 1; i <= 6; i++) {
    replaceMap[`{SKILL_LABEL_${i}}`] = cap(cv[`skill_${i}_label`]);
    replaceMap[`{SKILL_CONTENT_${i}}`] = cap(cv[`skill_${i}_content`]);
  }
  // 3 projects
  for (let i = 1; i <= 3; i++) {
    replaceMap[`{PROJECT_IDEA_${i}}`] = cap(_safe(() => cv[`project_${i}_title`], ''));
    replaceMap[`{PROJECT_${i}_AI_GENERATED_ALIGNED_TO_JD_REQUIREMENTS}`] = cap(_safe(() => cv[`project_${i}_desc`], ''));
  }
  // 4 certs
  for (let i = 1; i <= 4; i++) {
    replaceMap[`{CERTIFICATION_${i}_AI_GENERATED_ALIGNED_TO_JD_REQUIREMENTS}`] = cap(_safe(() => cv.certifications[i-1], ''));
  }

  const requests = Object.keys(replaceMap).map((k) => ({
    replaceAllText: {
      containsText: { text: k, matchCase: true },
      replaceText: replaceMap[k]
    }
  }));

  return [{
    json: {
      docId,
      body: JSON.stringify({ requests }),
      meta,
      replacement_count: requests.length,
      mode: 'healthcare'
    }
  }];
} catch (e) {
  throw new Error('Hc · Build Replacements failed: ' + (e && e.message ? e.message : String(e)));
}

// === FLAT_TO_WRAP_ADAPTER 2026-05-16 (fixes schema regression) ===
try {
  const _it = $input.first().json || {};
  if (_it && typeof _it === 'object' && typeof _it.stdout === 'string' && _it.stdout.length > 200) {
    let _parsed = null;
    try { _parsed = JSON.parse(_it.stdout); } catch(_) {}
    if (_parsed && typeof _parsed === 'object' && !_parsed.cv_content) {
      const _looksFlat = ('candidate_name' in _parsed) || ('role_1_bullets' in _parsed) || ('professional_summary' in _parsed) || ('skill_1_label' in _parsed);
      if (_looksFlat) {
        const _metaKeys = new Set(['model','mode','tier','effort','duration_s','job_id','engine','generation_mode','_usage','ok']);
        const cv = {};
        const meta = { mode: _parsed.mode||'', tier: _parsed.tier||'', model: _parsed.model||'', ss_job_id: _parsed.job_id||'' };
        for (const k of Object.keys(_parsed)) {
          if (_metaKeys.has(k)) continue;
          cv[k] = _parsed[k];
        }
        // map flat 'summary' -> professional_summary if not present
        if (!cv.professional_summary && cv.summary) cv.professional_summary = cv.summary;
        // map cert_1..4 -> certifications[]
        if (!cv.certifications) {
          const certs=[];
          for (let i=1;i<=4;i++) if (cv['cert_'+i]) certs.push(cv['cert_'+i]);
          if (certs.length) cv.certifications = certs;
        }
        // map project_N_name -> project_N_title, project_N_description -> project_N_desc
        for (let i=1;i<=3;i++) {
          if (cv['project_'+i+'_name'] && !cv['project_'+i+'_title']) cv['project_'+i+'_title'] = cv['project_'+i+'_name'];
          if (cv['project_'+i+'_description'] && !cv['project_'+i+'_desc']) cv['project_'+i+'_desc'] = cv['project_'+i+'_description'];
        }
        const _wrapped = JSON.stringify({ cv_content: cv, meta: meta });
        _it.stdout = _wrapped;
        _it._flat_wrapped = true;
      }
    }
  }
} catch(_adapterErr) { /* never block pipeline */ }
// === END FLAT_TO_WRAP_ADAPTER ===

// ===== EARLY UNWRAP SHIM (bulletproof v3 — 2026-05-13) =====
// === BULLETPROOF v4 — JSON repair on inner cv_content string ===
const _jsonRepair = (s) => {
  if (typeof s !== 'string') return null;
  let t = s.trim();
  // Try strict first
  try { return JSON.parse(t); } catch(_) {}
  // Strip markdown fences
  t = t.replace(/^```(?:json)?\s*/i,'').replace(/\s*```\s*$/,'');
  try { return JSON.parse(t); } catch(_) {}
  // Trim to last balanced brace
  let depth=0, lastGood=-1, inStr=false, esc=false;
  for (let i=0;i<t.length;i++){
    const c=t[i];
    if (esc){esc=false;continue;}
    if (c==='\\'){esc=true;continue;}
    if (c==='"'){inStr=!inStr;continue;}
    if (inStr) continue;
    if (c==='{') depth++;
    else if (c==='}'){depth--; if(depth===0) lastGood=i;}
  }
  if (lastGood>0){
    try { return JSON.parse(t.slice(0,lastGood+1)); } catch(_) {}
  }
  // Remove trailing commas before } or ]
  let t2 = t.replace(/,(\s*[}\]])/g,'$1');
  try { return JSON.parse(t2); } catch(_) {}
  // Escape lone double-quotes inside string values (heuristic: quote not preceded by backslash and not followed by , or : or })
  // Final attempt: extract first balanced {...} block via brute-force scan
  let start=t.indexOf('{');
  while(start>=0){
    depth=0;inStr=false;esc=false;
    for(let i=start;i<t.length;i++){
      const c=t[i];
      if (esc){esc=false;continue;}
      if (c==='\\'){esc=true;continue;}
      if (c==='"'){inStr=!inStr;continue;}
      if (inStr) continue;
      if (c==='{') depth++;
      else if (c==='}'){depth--; if(depth===0){
        try { return JSON.parse(t.slice(start,i+1)); } catch(_) { break; }
      }}
    }
    start=t.indexOf('{',start+1);
  }
  return null;
};
// === END v4 ===
// === OK_FALSE_EARLY_EXIT — Recognise runner failure (added 2026-05-14) ===
try {
  const _firstItem = $input.first().json || {};
  // Runner emits { ok: false, error: "...", stderr: "...", job_id, mode } on failure
  if (_firstItem && _firstItem.stdout && typeof _firstItem.stdout === 'string' && _firstItem.stdout.length < 500) {
    let _runnerOut = null;
    try { _runnerOut = JSON.parse(_firstItem.stdout); } catch(_) {}
    if (_runnerOut && _runnerOut.ok === false) {
      const _errMsg = _runnerOut.error || 'unknown runner error';
      const _stderr = (_runnerOut.stderr || '').slice(0, 300);
      const _jobId = _runnerOut.job_id || 'unknown';
      const _mode = _runnerOut.mode || 'unknown';
      throw new Error('RUNNER_FAILED [' + _mode + ' / ' + _jobId + ']: ' + _errMsg + (_stderr ? ' | stderr: ' + _stderr : ''));
    }
  }
} catch (_runnerCheckErr) {
  if (String(_runnerCheckErr.message || '').startsWith('RUNNER_FAILED')) throw _runnerCheckErr;
}
// === END OK_FALSE_EARLY_EXIT ===


// Strategies layered:
//   1. Deep recursive walk through priority keys, JSON.parsing strings.
//   2. Whole-input stringify → balanced-brace JSON candidate scan.
//   3. Detect CV by shape (cv_content object with substance OR meta with role/company).
// Failure mode: throws BULLETPROOF_FAIL with input diagnostic — never silent.
try {
  const __MODE__ = "professional";
  const __CONFIG_NODE__ = "Hc · Config";

  const _isObj = v => v && typeof v === 'object' && !Array.isArray(v);
  const _tryParse = s => { try { return JSON.parse(s); } catch (_) { return null; } };

  // v3.3: lenient — extract first balanced {...} from a string and parse it.
  // Handles 'Extra data' errors caused by runner emitting orphan trailing fields.
  const _parseLenient = (s) => {
    if (typeof s !== 'string') return null;
    const direct = _tryParse(s);
    if (direct) return direct;
    let depth = 0, start = -1, inStr = false, esc = false;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charAt(i);
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
        continue;
      }
      if (ch === '"') { inStr = true; continue; }
      if (ch === '{') { if (depth === 0) start = i; depth++; }
      else if (ch === '}') {
        depth--;
        if (depth === 0 && start >= 0) {
          const cand = s.slice(start, i + 1);
          const parsed = _tryParse(cand);
          if (parsed) {
            // v3.3: recover orphan trailing fields (e.g. ',"certifications":[...]')
            const tail = s.slice(i + 1).trim();
            if (tail && tail.charAt(0) === ',') {
              const recoveredObj = _tryParse('{' + tail.replace(/^,/, '').replace(/}\s*$/, '') + '}');
              if (recoveredObj && parsed && typeof parsed === 'object') {
                const target = (parsed.cv_content && typeof parsed.cv_content === 'object') ? parsed.cv_content : parsed;
                for (const k of Object.keys(recoveredObj)) {
                  if (target[k] === undefined) target[k] = recoveredObj[k];
                }
              }
            }
            return parsed;
          }
          start = -1;
        }
      }
    }
    return null;
  };

  const _looksLikeCV = (o) => {
    if (!_isObj(o)) return false;
    if (_isObj(o.cv_content)) {
      const c = o.cv_content;
      if (c.professional_summary || c.professional_tagline ||
          c.role_1_bullets || c.role_2_bullets || c.skill_1_label ||
          c.skill_1_content) return true;
    }
    if (_isObj(o.meta) && (o.meta.role_title || o.meta.company)) return true;
    return false;
  };

  const _PRIORITY = ['cv_content','structured_output','data','output','result',
                     'body','response','stdout','stdoutText','message','content',
                     'text','json','value','payload','raw'];

  const _findCV = (node, depth) => {
    depth = depth || 0;
    if (depth > 12 || node == null) return null;
    if (_looksLikeCV(node)) return node;
    if (typeof node === 'string') {
      const s = node.trim();
      if (s.length > 20 && (s.charAt(0) === '{' || s.charAt(0) === '[')) {
        const p = _tryParse(s);
        if (p) return _findCV(p, depth + 1);
        const lp = _parseLenient(s);
        if (lp) return _findCV(lp, depth + 1);
      }
      return null;
    }
    if (Array.isArray(node)) {
      for (let i = 0; i < node.length; i++) {
        const r = _findCV(node[i], depth + 1);
        if (r) return r;
      }
      return null;
    }
    if (_isObj(node)) {
      for (let i = 0; i < _PRIORITY.length; i++) {
        const k = _PRIORITY[i];
        if (k in node) { const r = _findCV(node[k], depth + 1); if (r) return r; }
      }
      const keys = Object.keys(node);
      for (let i = 0; i < keys.length; i++) {
        if (_PRIORITY.indexOf(keys[i]) >= 0) continue;
        const r = _findCV(node[keys[i]], depth + 1);
        if (r) return r;
      }
    }
    return null;
  };

  // Strategy 2: balanced-brace scan over any large string in the input
  const _braceCandidates = (s) => {
    const out = [];
    if (typeof s !== 'string' || s.length < 30) return out;
    let depth = 0, start = -1, inStr = false, esc = false;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charAt(i);
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
        continue;
      }
      if (ch === '"') { inStr = true; continue; }
      if (ch === '{') { if (depth === 0) start = i; depth++; }
      else if (ch === '}') {
        depth--;
        if (depth === 0 && start >= 0) {
          const cand = s.slice(start, i + 1);
          if (cand.length > 50 && (cand.indexOf('cv_content') >= 0 || cand.indexOf('role_title') >= 0)) {
            out.push(cand);
          }
          start = -1;
        }
      }
    }
    return out;
  };

  const _allStrings = (node, depth, out) => {
    out = out || [];
    depth = depth || 0;
    if (depth > 8 || node == null) return out;
    if (typeof node === 'string') { if (node.length > 30) out.push(node); return out; }
    if (Array.isArray(node)) { for (const x of node) _allStrings(x, depth + 1, out); return out; }
    if (_isObj(node)) { for (const k of Object.keys(node)) _allStrings(node[k], depth + 1, out); return out; }
    return out;
  };

  const _scanFallback = (raw) => {
    const seen = new Set();
    const strings = _allStrings(raw);
    try { strings.push(JSON.stringify(raw)); } catch (_) {}
    for (const s of strings) {
      const cands = _braceCandidates(s);
      for (const c of cands) {
        if (seen.has(c)) continue;
        seen.add(c);
        const p = _tryParse(c);
        if (!p) continue;
        const hit = _findCV(p);
        if (hit) return hit;
      }
    }
    return null;
  };

  const _findOuter = (node, depth) => {
    depth = depth || 0;
    if (depth > 8 || node == null) return null;
    if (_isObj(node)) {
      if (node._usage || node.model || node.tier || node.duration_s ||
          node.job_id || node.cost_usd) return node;
      for (let i = 0; i < _PRIORITY.length; i++) {
        const k = _PRIORITY[i];
        if (k in node) {
          const v = node[k];
          if (typeof v === 'string') {
            const p = _tryParse(v);
            if (p) { const r = _findOuter(p, depth + 1); if (r) return r; }
          } else {
            const r = _findOuter(v, depth + 1); if (r) return r;
          }
        }
      }
    }
    if (typeof node === 'string') {
      const p = _tryParse(node);
      if (p) return _findOuter(p, depth + 1);
    }
    return null;
  };

  const _all = (function(){ try { return $input.all().map(x => x && x.json).filter(Boolean); } catch(_) { try { return [$input.first().json]; } catch(__) { return []; } } })();
  const _fastPath = () => {
    for (const _it of _all) {
      if (!_isObj(_it)) continue;
      const raw = typeof _it.stdout === 'string' ? _it.stdout : (typeof _it.result === 'string' ? _it.result : null);
      if (!raw) continue;
      const outer = _parseLenient(raw.trim());
      if (!outer) continue;
      let candidate = outer;
      if (_isObj(outer) && typeof outer.cv_content === 'string' && outer.cv_content.trim().startsWith('{')) {
        const inner = _jsonRepair(outer.cv_content) || _parseLenient(outer.cv_content);
        if (inner && _isObj(inner)) {
          if (_isObj(inner.cv_content)) candidate = inner;
          else candidate = { ...outer, cv_content: inner };
        }
      }
      if (_looksLikeCV(candidate)) return candidate;
      if (_isObj(candidate)) {
        for (const k of Object.keys(candidate)) if (_looksLikeCV(candidate[k])) return candidate[k];
      }
    }
    return null;
  };
  const _raw = _all[0];
  let _cv = _fastPath();
  let _strategy_used = _cv ? "fastpath" : null;
  if (!_cv) { for (const _it of _all) { _cv = _findCV(_it); if (_cv) { _strategy_used = "walk"; break; } } }

  if (!_cv) { for (const _it of _all) { _cv = _scanFallback(_it); if (_cv) { _strategy_used = 'brace_scan'; break; } } }


  // === REGEX SYNTH FALLBACK v1 — 2026-05-17 ===
  // When inner JSON is unparseable (Claude occasionally emits stray ] inside
  // string values, e.g. '...crash-free."]' — confirmed in execs 620/627),
  // walk raw stdout strings and synthesize cv_content from per-field regex
  // matches. Prevents BULLETPROOF_NO_CV throws on ~14% of cron runs where
  // the model output is structurally broken but individual field values are
  // still extractable. Downstream COMPLETENESS / AI-TELL guards still police.
  if (!_cv) {
    try {
      const _rawStrings = [];
      for (const _it of _all) {
        if (!_isObj(_it)) continue;
        if (typeof _it.stdout === "string") _rawStrings.push(_it.stdout);
        if (typeof _it.result === "string") _rawStrings.push(_it.result);
        const _o1 = _tryParse(typeof _it.stdout === "string" ? _it.stdout : "");
        if (_o1 && typeof _o1.cv_content === "string") _rawStrings.push(_o1.cv_content);
      }
      const _grabStr = (text, key) => {
        const re = new RegExp('"' + key + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"');
        const m = text.match(re);
        if (!m) return "";
        try { return JSON.parse('"' + m[1] + '"'); } catch (_) { return m[1]; }
      };
      const _grabArr = (text, key) => {
        const re = new RegExp('"' + key + '"\\s*:\\s*(\\[[\\s\\S]*?\\])(?=\\s*[,}])');
        const m = text.match(re);
        if (!m) return null;
        const arr = _tryParse(m[1]);
        if (Array.isArray(arr)) return arr.map(x => typeof x === "string" ? x : String(x));
        const items = [];
        const sre = /"((?:[^"\\\\]|\\\\.)*)"/g;
        let mm;
        while ((mm = sre.exec(m[1])) !== null) {
          try { items.push(JSON.parse('"' + mm[1] + '"')); } catch (_) { items.push(mm[1]); }
        }
        return items.length ? items : null;
      };
      const _synth = {};
      for (const _src of _rawStrings) {
        if (!_src || typeof _src !== "string") continue;
        const _try = (k) => { if (!_synth[k]) { const v = _grabStr(_src, k); if (v) _synth[k] = v; } };
        const _tryArr = (k) => { if (!_synth[k]) { const v = _grabArr(_src, k); if (v && v.length) _synth[k] = v; } };
        _try("professional_tagline");
        _try("professional_summary");
        for (let r = 1; r <= 6; r++) _tryArr("role_" + r + "_bullets");
        for (let p = 1; p <= 4; p++) {
          _try("project_" + p + "_title");
          _try("project_" + p + "_desc");
          _try("project_" + p + "_name");
          _try("project_" + p + "_description");
        }
        for (let s = 1; s <= 8; s++) {
          _try("skill_" + s + "_label");
          _try("skill_" + s + "_content");
        }
        for (let c = 1; c <= 4; c++) _try("cert_" + c);
        _tryArr("certifications");
      }
      for (let p = 1; p <= 4; p++) {
        if (_synth["project_" + p + "_name"] && !_synth["project_" + p + "_title"]) _synth["project_" + p + "_title"] = _synth["project_" + p + "_name"];
        if (_synth["project_" + p + "_description"] && !_synth["project_" + p + "_desc"]) _synth["project_" + p + "_desc"] = _synth["project_" + p + "_description"];
      }
      if (!_synth.certifications) {
