const totalIv = applied.filter(isIv).length;
const overall = totalApplied ? Math.round(100 * totalIv / totalApplied) : 0;
const ivScores = applied.filter(isIv).map(r => num(r['SCORE'])).sort((a, b) => a - b);
const medianIv = ivScores.length ? ivScores[Math.floor(ivScores.length / 2)] : null;
const lowestIv = ivScores.length ? ivScores[0] : null;

let verdict, advice, vColor;
if (totalIv < 5) {
  verdict = 'NOT ENOUGH DATA YET'; vColor = '#FBF6E7';
  advice = 'Only ' + totalIv + ' interviews logged across ' + totalApplied + ' applied CVs. Keep filling the INTERVIEW? column in the tracker — this becomes meaningful at about 5 or more interviews.';
} else if (miscal) {
  verdict = 'MISCALIBRATED'; vColor = '#F5E4DD';
  advice = 'A lower score band is getting interviews at least as often as a higher band, so the score is not tracking real outcomes. Tighten the rubric or re-weight the dimensions.';
} else {
  verdict = 'CALIBRATED'; vColor = '#EAF4E7';
  advice = 'Interview rate rises with score as it should. Interviews start around score ' + lowestIv + ' and the median interviewed CV scored ' + medianIv + '. Treat ' + medianIv + ' as your real worth-applying line.';
}

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = { ink:'#0B0F14', accent:'#D4FF3A', muted:'#6E7079', line:'#E6E4DE', surface:'#ffffff', paper:'#FAFAF7' };
const bar = rate => {
  if (rate == null) return '<span style="color:#888;">no data</span>';
  const col = rate >= 40 ? '#2F7D4D' : rate >= 20 ? '#C9A227' : '#9D432B';
  return '<span style="display:inline-block;width:120px;height:10px;background:#EEE;border-radius:5px;vertical-align:middle;overflow:hidden;"><span style="display:inline-block;width:' + Math.max(2, rate) + '%;height:10px;background:' + col + ';"></span></span> ' + rate + '%';
};
const rowsHtml = stats.map(s => '<tr><td style="padding:8px 10px;font-weight:700;border-bottom:1px solid ' + C.line + ';">' + s.key + '</td><td style="padding:8px 10px;border-bottom:1px solid ' + C.line + ';">' + (s.n || 0) + '</td><td style="padding:8px 10px;border-bottom:1px solid ' + C.line + ';">' + (s.iv || 0) + '</td><td style="padding:8px 10px;border-bottom:1px solid ' + C.line + ';">' + bar(s.rate) + '</td></tr>').join('');

const digestSubject = 'Resumae · Scorer Calibration — ' + verdict + ' · ' + totalIv + '/' + totalApplied + ' interviews (' + overall + '%)';
const digestHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>'
  + '<body style="margin:0;padding:24px 12px;background:' + C.paper + ';font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Helvetica,Arial,sans-serif;color:' + C.ink + ';">'
  + '<div style="max-width:680px;margin:0 auto;background:' + C.surface + ';border:1px solid ' + C.line + ';border-radius:14px;overflow:hidden;">'
  + '<div style="background:' + C.ink + ';color:' + C.paper + ';padding:28px 32px;"><div style="font-size:10px;text-transform:uppercase;letter-spacing:2px;font-weight:700;color:' + C.accent + ';">Resumae · Scorer Calibration</div>'
  + '<h1 style="margin:10px 0 4px;font-size:24px;font-weight:800;">' + esc(verdict) + '</h1>'
  + '<div style="font-size:14px;color:#C9CCD1;">' + totalIv + ' interviews from ' + totalApplied + ' applied CVs · overall ' + overall + '%</div></div>'
  + '<div style="padding:24px 32px;">'
  + '<p style="font-size:13px;color:' + C.muted + ';margin:0 0 16px;">Reads your Apply Tracker (only APPLIED=YES rows) and checks the one thing that matters: does interview rate go UP as the score goes up?</p>'
  + '<table style="width:100%;border-collapse:collapse;font-size:13px;"><tr style="text-align:left;color:' + C.muted + ';font-size:11px;text-transform:uppercase;letter-spacing:1px;"><th style="padding:6px 10px;">Score band</th><th style="padding:6px 10px;">Applied</th><th style="padding:6px 10px;">Interviews</th><th style="padding:6px 10px;">Interview rate</th></tr>' + rowsHtml + '</table>'
  + '<div style="margin-top:18px;padding:14px 16px;border-radius:8px;background:' + vColor + ';font-size:13px;line-height:1.5;"><b>Verdict: ' + esc(verdict) + '</b><br>' + esc(advice) + '</div>'
  + '<div style="margin-top:16px;font-size:12px;color:' + C.muted + ';">Ground truth = <a href="https://docs.google.com/spreadsheets/d/139VB0qXcKd2s5jtjHNGtNxotpVrhmx_xU55m4kX2_B0/edit" style="color:' + C.ink + ';">Apply Tracker</a>. The more you fill the INTERVIEW? column, the sharper this gets. This is what decides your real score boundaries — not a guess.</div>'
  + '</div></div></body></html>';

return [{ json: { digestSubject, digestHtml, calib: { verdict, stats, totalApplied, totalIv, overall, medianIv } } }];

// Resumae · Stuck-Row Reaper — detection logic (SAFE, ADDITIVE — touches nothing in the main workflow).
// Runs once per reaper cycle over the rows the read node returned (STATUS == "processing").
// Column K = REAPER_SEEN holds an epoch-millisecond sentinel written ONLY by this workflow.

const STUCK_AFTER_MS = 32 * 60 * 1000;   // #6 2026-07: raised 14->32 min, ABOVE the runner's 30-min
                                         // timeout, so a legitimately long generation is never
                                         // false-failed; only genuinely stuck rows (>32 min) are caught.
const RETRY_CAP = 1;                     // #2 2026-07: bounded auto-requeue — retry a stuck row this
                                         // many times (STATUS->pending) before giving up (STATUS->failed).
const STALE_MAX_MS   = 3 * 60 * 60 * 1000; // a stamp older than this is treated as a leftover from a
                                         // previous episode (e.g. a manually re-queued row): it is
                                         // RE-STAMPED, not failed. Prime directive: never kill in-flight.

const now = Date.now();
const stamp = String(now);               // epoch ms as text — round-trips through Sheets exactly
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const status = String(j.STATUS ?? '').trim().toLowerCase();
  if (status !== 'processing') continue;         // safety: only ever act on processing rows

  const rowNumber = j.row_number;
  if (rowNumber === undefined || rowNumber === null || rowNumber === '') continue;

  const seenRaw = String(j.REAPER_SEEN ?? '').trim();
  const seenMs  = Number(seenRaw);
  const seen    = seenRaw !== '' && Number.isFinite(seenMs) && seenMs > 0;
  const elapsed = seen ? now - seenMs : 0;
  const retryCount = Number(String(j.RETRY_COUNT ?? '').trim()) || 0;  // #2 bounded requeue counter

  if (!seen || elapsed > STALE_MAX_MS) {
    // First sighting (or a stale leftover stamp) -> record now(); give it a fresh window. Do NOT fail.
    out.push({ json: { _action: 'stamp', row_number: rowNumber, REAPER_SEEN: stamp } });
  } else if (elapsed > STUCK_AFTER_MS) {
    // Seen a previous cycle AND still processing beyond the threshold -> genuinely STUCK.
    // #2 2026-07 (owner-approved): bounded auto-requeue. Put the row back to 'pending' (up to
    // RETRY_CAP times) so it is reprocessed automatically; only mark 'failed' once retries exhausted.
    const _willRetry = retryCount < RETRY_CAP;
    out.push({ json: {
      _action: 'fail',                    // routed to Queue: Mark Failed (which now writes STATUS dynamically)
      row_number: rowNumber,
      STATUS: _willRetry ? 'pending' : 'failed',
      RETRY_COUNT: _willRetry ? (retryCount + 1) : retryCount,
      'DONE?': 'FALSE',
      REAPER_SEEN: '',                    // clear the sentinel so a requeued row gets a fresh timing window
      minutesStuck: Math.round(elapsed / 60000),
      NAME: j.NAME ?? '',
      JD: j.JD ?? '',
      URL: j.URL ?? '',
      TIER: j.TIER ?? '',
      MODE: j.MODE ?? '',
    } });
  }
  // else: seen recently (<= threshold) -> healthy in-flight job, leave it completely alone.
}

return out;

